import { readFileSync } from "node:fs";

const prs = JSON.parse(readFileSync("prs.json", "utf8"));
const teamOf = JSON.parse(readFileSync("teams.json", "utf8")); // GitHub login -> team

const hours = (from, to) => (Date.parse(to) - Date.parse(from)) / 3_600_000;
const quantile = (values, q) => {
  const s = values.toSorted((a, b) => a - b);
  const i = (s.length - 1) * q, lo = Math.floor(i), hi = Math.ceil(i);
  return s[lo] + (s[hi] - s[lo]) * (i - lo);
};
const mondayOf = (iso) => {
  const d = new Date(iso);
  d.setUTCHours(0, 0, 0, 0);
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
  return d.getTime();
};

const readyAt = (pr) => pr.timeline.find((e) => e.__typename === "ReadyForReviewEvent")?.createdAt ?? pr.createdAt;
const reviewWaitHours = (pr) => {
  const first = pr.timeline.find((e) => e.__typename === "PullRequestReview"
    && e.author.__typename === "User" && e.author.login !== pr.author.login);
  return first ? hours(readyAt(pr), first.createdAt) : undefined;
};

const groups = new Map(); // "team|week" -> the review waits of that team's PRs in that week
for (const pr of prs) {
  const wait = reviewWaitHours(pr);
  if (wait === undefined) continue;
  const key = `${teamOf[pr.author.login]}|${mondayOf(readyAt(pr))}`;
  groups.set(key, [...(groups.get(key) ?? []), wait]);
}
for (const [key, waits] of groups) {
  const [team, week] = key.split("|");
  if (waits.length < 2) continue;
  console.log(`delivery_review_wait_hours{team="${team}",q="p50"} ${quantile(waits, 0.5).toFixed(1)} ${week}`);
}
EOF

